// internal/scheduling/service.go
package scheduling

import (
	"context"
	"errors"
	"fmt"
	"log"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// GenerationWindow is how far ahead we materialize occurrences.
// Beyond this, series are regenerated by the background worker.
const GenerationWindow = 90 * 24 * time.Hour

type Service struct {
	repo *Repository
	db   *pgxpool.Pool
}

func NewService(repo *Repository, db *pgxpool.Pool) *Service {
	return &Service{repo: repo, db: db}
}

// Pauser adapter — this is what `groups.Service.Archive` will call.
// We implement it as a method on a small adapter type so there's no import cycle.
type Pauser struct{ svc *Service }

func (s *Service) AsPauser() Pauser { return Pauser{svc: s} }

func (p Pauser) PauseGroupActivity(ctx context.Context, tx pgx.Tx, groupID string) error {
	return p.svc.repo.PauseSeriesByGroup(ctx, tx, groupID)
}

// ==================== Create series ====================

func (s *Service) CreateSeries(ctx context.Context, actorID, groupID string, req CreateSeriesRequest) (*Series, error) {
	// Static validation.
	if _, err := parseRRule(req.RecurrenceRule); err != nil {
		return nil, fmt.Errorf("%w: %v", ErrInvalidRRule, err)
	}
	if _, err := time.LoadLocation(req.Timezone); err != nil {
		return nil, fmt.Errorf("invalid timezone: %w", err)
	}
	localStart, err := normalizeTime(req.LocalStartTime)
	if err != nil {
		return nil, err
	}
	startsOn, err := time.Parse("2006-01-02", req.StartsOn)
	if err != nil {
		return nil, fmt.Errorf("invalid startsOn: %w", err)
	}
	var endsOn *time.Time
	if req.EndsOn != nil {
		d, err := time.Parse("2006-01-02", *req.EndsOn)
		if err != nil {
			return nil, fmt.Errorf("invalid endsOn: %w", err)
		}
		if d.Before(startsOn) {
			return nil, ErrInvalidTime
		}
		endsOn = &d
	}

	tx, err := s.db.Begin(ctx)
	if err != nil {
		return nil, err
	}
	defer tx.Rollback(ctx)

	// Actor must be moderator+.
	if _, err := s.requireGroupRole(ctx, tx, groupID, actorID, RoleModerator); err != nil {
		return nil, err
	}
	// Room must belong to the group; composite FK enforces this at the DB,
	// but we do a friendly check so we can return a clean error.
	if req.RoomID != nil {
		var ok bool
		err := tx.QueryRow(ctx,
			`SELECT EXISTS (SELECT 1 FROM study_rooms
			                 WHERE id = $1::uuid AND group_id = $2::uuid
			                   AND archived_at IS NULL)`,
			*req.RoomID, groupID).Scan(&ok)
		if err != nil {
			return nil, err
		}
		if !ok {
			return nil, ErrNoRoom
		}
	}

	series := &Series{
		GroupID:         groupID,
		RoomID:          req.RoomID,
		CreatedBy:       actorID,
		Title:           strings.TrimSpace(req.Title),
		Description:     req.Description,
		Timezone:        req.Timezone,
		RecurrenceRule:  req.RecurrenceRule,
		LocalStartTime:  localStart,
		DurationSeconds: req.DurationSeconds,
		StartsOn:        startsOn,
		EndsOn:          endsOn,
	}
	if err := s.repo.InsertSeries(ctx, tx, series); err != nil {
		return nil, err
	}

	// Generate the first window inside the same tx. So CreateSeries either
	// creates the plan AND its first occurrences, or nothing.
	windowEnd := time.Now().Add(GenerationWindow)
	if err := s.generateTx(ctx, tx, series, time.Now(), windowEnd); err != nil {
		return nil, fmt.Errorf("generate first window: %w", err)
	}

	// Record the high-water mark so the worker doesn't redo this window.
	if _, err := tx.Exec(ctx,
		`UPDATE study_session_series SET generated_until = $2 WHERE id = $1::uuid`,
		series.ID, windowEnd); err != nil {
		return nil, err
	}

	if err := tx.Commit(ctx); err != nil {
		return nil, err
	}
	return series, nil
}

// generateTx is the shared generator: expand window, insert occurrences
// (idempotent), inside the caller's transaction.
func (s *Service) generateTx(ctx context.Context, tx pgx.Tx, series *Series, from, to time.Time) error {
	starts, err := occurrencesBetween(series, from, to)
	if err != nil {
		return err
	}
	for _, start := range starts {
		end := start.Add(time.Duration(series.DurationSeconds) * time.Second)
		occurrenceStart := start
		sess := &Session{
			GroupID:          series.GroupID,
			RoomID:           series.RoomID,
			SeriesID:         &series.ID,
			OriginalStartsAt: &occurrenceStart,
			CreatedBy:        series.CreatedBy,
			Title:            series.Title,
			Description:      series.Description,
			StartsAt:         start,
			EndsAt:           end,
		}
		if _, err := s.repo.InsertSession(ctx, tx, sess); err != nil {
			return err
		}
	}
	return nil
}

// ==================== Read series ====================

func (s *Service) GetSeries(ctx context.Context, actorID, seriesID string) (*Series, error) {
	ser, err := s.repo.GetSeriesByID(ctx, s.db, seriesID)
	if errors.Is(err, ErrNotFound) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	// Must be at least a member to see.
	if _, err := s.requireGroupRole(ctx, s.db, ser.GroupID, actorID, RoleMember); err != nil {
		return nil, err
	}
	return ser, nil
}

// ==================== Update series ====================

func (s *Service) UpdateSeries(ctx context.Context, actorID, seriesID string, req UpdateSeriesRequest) error {
	tx, err := s.db.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)

	ser, err := s.repo.GetSeriesByID(ctx, tx, seriesID)
	if errors.Is(err, ErrNotFound) {
		return ErrNotFound
	}
	if err != nil {
		return err
	}
	if _, err := s.requireGroupRole(ctx, tx, ser.GroupID, actorID, RoleModerator); err != nil {
		return err
	}
	if ser.Status == "ended" {
		return ErrSeriesEnded
	}

	var localStart *string
	if req.LocalStartTime != nil {
		norm, err := normalizeTime(*req.LocalStartTime)
		if err != nil {
			return err
		}
		localStart = &norm
	}
	if err := s.repo.UpdateSeries(ctx, tx, seriesID, UpdateSeriesFields{
		RoomID:          req.RoomID,
		Title:           req.Title,
		Description:     req.Description,
		LocalStartTime:  localStart,
		DurationSeconds: req.DurationSeconds,
	}); err != nil {
		return err
	}

	// Note: we do NOT retroactively rewrite future occurrences. Changes to
	// a series shape affect only occurrences generated *after* this point.
	// Existing occurrences are immutable so attendance history stays intact.
	// (If you want a "regenerate future" flag, add it explicitly later.)
	return tx.Commit(ctx)
}

// ==================== End series ====================

// EndSeries sets status='ended' — no new occurrences will be generated, but
// existing scheduled occurrences remain (they may still happen).
func (s *Service) EndSeries(ctx context.Context, actorID, seriesID string) error {
	tx, err := s.db.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)

	ser, err := s.repo.GetSeriesByID(ctx, tx, seriesID)
	if errors.Is(err, ErrNotFound) {
		return ErrNotFound
	}
	if err != nil {
		return err
	}
	if _, err := s.requireGroupRole(ctx, tx, ser.GroupID, actorID, RoleModerator); err != nil {
		return err
	}
	if err := s.repo.SetSeriesStatus(ctx, tx, seriesID, "ended"); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

// ==================== Create one-off session ====================

func (s *Service) CreateSession(ctx context.Context, actorID, groupID string, req CreateSessionRequest) (*Session, error) {
	startsAt, err := time.Parse(time.RFC3339, req.StartsAt)
	if err != nil {
		return nil, fmt.Errorf("invalid startsAt: %w", err)
	}
	endsAt, err := time.Parse(time.RFC3339, req.EndsAt)
	if err != nil {
		return nil, fmt.Errorf("invalid endsAt: %w", err)
	}
	if !endsAt.After(startsAt) {
		return nil, ErrInvalidTime
	}
	if endsAt.Sub(startsAt) > 24*time.Hour {
		return nil, ErrInvalidTime
	}

	tx, err := s.db.Begin(ctx)
	if err != nil {
		return nil, err
	}
	defer tx.Rollback(ctx)

	if _, err := s.requireGroupRole(ctx, tx, groupID, actorID, RoleModerator); err != nil {
		return nil, err
	}
	if req.RoomID != nil {
		var ok bool
		if err := tx.QueryRow(ctx,
			`SELECT EXISTS (SELECT 1 FROM study_rooms
			                 WHERE id = $1::uuid AND group_id = $2::uuid
			                   AND archived_at IS NULL)`,
			*req.RoomID, groupID).Scan(&ok); err != nil {
			return nil, err
		}
		if !ok {
			return nil, ErrNoRoom
		}
	}

	sess := &Session{
		GroupID:     groupID,
		RoomID:      req.RoomID,
		CreatedBy:   actorID,
		Title:       strings.TrimSpace(req.Title),
		Description: req.Description,
		StartsAt:    startsAt.UTC(),
		EndsAt:      endsAt.UTC(),
	}
	if _, err := s.repo.InsertSession(ctx, tx, sess); err != nil {
		return nil, err
	}
	if err := tx.Commit(ctx); err != nil {
		return nil, err
	}
	return sess, nil
}

// ==================== Read sessions ====================

func (s *Service) GetSession(ctx context.Context, actorID, sessionID string) (*SessionDetail, error) {
	d, err := s.repo.GetSessionDetail(ctx, s.db, sessionID)
	if errors.Is(err, ErrNotFound) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	role, err := s.requireGroupRole(ctx, s.db, d.GroupID, actorID, RoleMember)
	if err != nil {
		return nil, err
	}
	d.MyRole = role
	return d, nil
}

func (s *Service) ListSessions(ctx context.Context, actorID string, f ListFilter) ([]SessionDetail, error) {
	if _, err := s.requireGroupRole(ctx, s.db, f.GroupID, actorID, RoleMember); err != nil {
		return nil, err
	}
	return s.repo.ListSessions(ctx, s.db, f)
}

// ==================== Update / cancel session ====================

func (s *Service) UpdateSession(ctx context.Context, actorID, sessionID string, req UpdateSessionRequest) error {
	tx, err := s.db.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)

	sess, err := s.repo.GetSessionByID(ctx, tx, sessionID)
	if errors.Is(err, ErrNotFound) {
		return ErrNotFound
	}
	if err != nil {
		return err
	}
	if _, err := s.requireGroupRole(ctx, tx, sess.GroupID, actorID, RoleModerator); err != nil {
		return err
	}
	if sess.Status != "scheduled" {
		return ErrSessionLocked
	}

	f := UpdateSessionFields{
		RoomID:      req.RoomID,
		Title:       req.Title,
		Description: req.Description,
	}
	if req.StartsAt != nil {
		t, err := time.Parse(time.RFC3339, *req.StartsAt)
		if err != nil {
			return fmt.Errorf("invalid startsAt: %w", err)
		}
		f.StartsAt = &t
	}
	if req.EndsAt != nil {
		t, err := time.Parse(time.RFC3339, *req.EndsAt)
		if err != nil {
			return fmt.Errorf("invalid endsAt: %w", err)
		}
		f.EndsAt = &t
	}
	// If either time changed, they must still be consistent.
	start := sess.StartsAt
	end := sess.EndsAt
	if f.StartsAt != nil {
		start = *f.StartsAt
	}
	if f.EndsAt != nil {
		end = *f.EndsAt
	}
	if !end.After(start) || end.Sub(start) > 24*time.Hour {
		return ErrInvalidTime
	}

	if err := s.repo.UpdateSession(ctx, tx, sessionID, f); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

func (s *Service) CancelSession(ctx context.Context, actorID, sessionID string) error {
	tx, err := s.db.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)

	sess, err := s.repo.GetSessionByID(ctx, tx, sessionID)
	if errors.Is(err, ErrNotFound) {
		return ErrNotFound
	}
	if err != nil {
		return err
	}
	if _, err := s.requireGroupRole(ctx, tx, sess.GroupID, actorID, RoleModerator); err != nil {
		return err
	}
	if err := s.repo.CancelSession(ctx, tx, sessionID); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

// ==================== the gate ====================

// requireGroupRole mirrors groups.requireRole. Non-member → NotFound
// (anti-enumeration). Non-active → Forbidden. Role too low → Forbidden.
func (s *Service) requireGroupRole(ctx context.Context, ex pgxExecutor, groupID, userID string, need Role) (Role, error) {
	var roleStr, status string
	err := ex.QueryRow(ctx,
		`SELECT role::text, status
		   FROM group_memberships
		  WHERE group_id = $1::uuid AND user_id = $2::uuid
		  FOR SHARE`,
		groupID, userID).Scan(&roleStr, &status)
	if errors.Is(err, pgx.ErrNoRows) {
		return RoleNone, ErrNotFound
	}
	if err != nil {
		return RoleNone, err
	}
	if status != "active" {
		return RoleNone, ErrForbidden
	}
	r := ParseRole(roleStr)
	if r < need {
		return RoleNone, ErrForbidden
	}
	return r, nil
}

// ==================== rolling window worker ====================

// RunGenerator periodically extends the generation window for all active series.
// Call as: go svc.RunGenerator(ctx, time.Hour)
func (s *Service) RunGenerator(ctx context.Context, every time.Duration) {
	tick := time.NewTicker(every)
	defer tick.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-tick.C:
			if err := s.ExtendWindow(ctx); err != nil {
				log.Printf("scheduling: extend window: %v", err)
			}
		}
	}
}

// ExtendWindow processes active series that are behind on generation.
// Each series is handled in its own transaction so one failure doesn't
// block the rest.
func (s *Service) ExtendWindow(ctx context.Context) error {
	now := time.Now()
	cutoff := now.Add(GenerationWindow)

	// Find series that need work. Uses the partial index
	// study_session_series_generation_idx.
	rows, err := s.repo.ExtendGenerationWindow(ctx, s.db, cutoff)
	if err != nil {
		return err
	}
	if len(rows) == 0 {
		return nil
	}

	for _, ser := range rows {
		if err := s.extendOne(ctx, &ser, now, cutoff); err != nil {
			log.Printf("scheduling: series %s: %v", ser.ID, err)
			// Continue with the next series; don't let one bad one block others.
		}
	}
	return nil
}

func (s *Service) extendOne(ctx context.Context, ser *Series, from, to time.Time) error {
	tx, err := s.db.Begin(ctx)
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)

	// From: current generated_until (or now if null). Avoid regenerating.
	genFrom := from
	if ser.GeneratedUntil != nil && ser.GeneratedUntil.After(from) {
		genFrom = *ser.GeneratedUntil
	}

	if err := s.generateTx(ctx, tx, ser, genFrom, to); err != nil {
		return err
	}
	if _, err := tx.Exec(ctx,
		`UPDATE study_session_series SET generated_until = $2 WHERE id = $1::uuid`,
		ser.ID, to); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

// ==================== helpers ====================

// normalizeTime accepts "HH:MM" or "HH:MM:SS" and returns "HH:MM:SS".
func normalizeTime(s string) (string, error) {
	switch len(s) {
	case 5: // "HH:MM"
		if _, err := time.Parse("15:04", s); err != nil {
			return "", fmt.Errorf("invalid time: %w", err)
		}
		return s + ":00", nil
	case 8: // "HH:MM:SS"
		if _, err := time.Parse("15:04:05", s); err != nil {
			return "", fmt.Errorf("invalid time: %w", err)
		}
		return s, nil
	default:
		return "", fmt.Errorf("time must be HH:MM or HH:MM:SS")
	}
}